nginx_config:
daemon off;
master_process on;
worker_processes 2;
pid /tmp/aegisx-bench-wplfmyox/nginx.pid;
error_log /tmp/aegisx-bench-wplfmyox/nginx-error.log crit;
events { worker_connections 16384; multi_accept on; }
http {
    access_log off;
    client_body_temp_path /tmp/aegisx-bench-wplfmyox/body;
    proxy_temp_path /tmp/aegisx-bench-wplfmyox/proxy;
    keepalive_timeout 60s;
    keepalive_requests 100000;

    upstream origin { server 10.42.1.170:3900; keepalive 256; }
    server {
        listen 10.42.1.79:35809   reuseport;
        location / {
            proxy_http_version 1.1;
            proxy_set_header Connection "";
            proxy_set_header Host 10.42.1.170:3900;
            proxy_request_buffering off;
            proxy_buffering off;
            proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
            proxy_set_header X-Forwarded-Proto $scheme;
            proxy_set_header X-Request-Id $request_id;
            add_header X-Request-Id $request_id;
            proxy_pass http://origin;
        }
    }
}
